'use client'

import { useEffect } from 'react'
import { usePathname } from 'next/navigation'

let previousPath = ''

export function ViewTransitions() {
  const pathname = usePathname()

  useEffect(() => {
    // Store initial path
    if (!previousPath) {
      previousPath = pathname
    }
  }, [pathname])

  useEffect(() => {
    const handleClick = (e: MouseEvent) => {
      const target = e.target as HTMLElement
      const link = target.closest('a')

      if (
        !link ||
        link.target === '_blank' ||
        link.hostname !== window.location.hostname ||
        e.metaKey ||
        e.ctrlKey ||
        e.shiftKey ||
        e.altKey
      ) {
        return
      }

      // Check if browser supports View Transitions
      if (!document.startViewTransition) return

      const targetUrl = new URL(link.href)
      const currentPath = window.location.pathname
      const targetPath = targetUrl.pathname

      // Determine navigation direction
      const isNavigatingToDetail = targetPath.includes('/product/')
      const isNavigatingBack = !isNavigatingToDetail && currentPath.includes('/product/')

      e.preventDefault()

      // Set direction class on document
      document.documentElement.classList.add(
        isNavigatingBack ? 'back-navigation' : 'forward-navigation'
      )

      const transition = document.startViewTransition(async () => {
        window.history.pushState({}, '', link.href)

        // Trigger Next.js navigation
        const event = new PopStateEvent('popstate', { state: {} })
        window.dispatchEvent(event)
      })

      transition.finished.finally(() => {
        document.documentElement.classList.remove('back-navigation', 'forward-navigation')
      })
    }

    document.addEventListener('click', handleClick)
    return () => document.removeEventListener('click', handleClick)
  }, [])

  return null
}

