/* View Transitions */
@media (prefers-reduced-motion: no-preference) {
  /* Directional slide transitions for page navigation */
  ::view-transition-old(root) {
    animation: slide-out-to-left 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  }

  ::view-transition-new(root) {
    animation: slide-in-from-right 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  }

  /* Reverse direction for back navigation */
  .back-navigation::view-transition-old(root) {
    animation: slide-out-to-right 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  }

  .back-navigation::view-transition-new(root) {
    animation: slide-in-from-left 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  }

  /* Shared element transition for product images */
  ::view-transition-old(product-image),
  ::view-transition-new(product-image) {
    animation: none;
    mix-blend-mode: normal;
  }

  /* Smooth morph for all product images */
  [style*='view-transition-name: product-'] {
    view-transition-name: product-image;
  }

  /* Skeleton to content transition */
  .skeleton-image,
  .skeleton-text {
    animation:
      pulse 1.5s ease-in-out infinite,
      fade-in 0.4s ease-out;
  }

  /* Content fade-in after suspense */
  .product-info {
    animation: fade-in 0.4s ease-out;
  }
}

