import { usePathname, useRouter } from 'next/navigation'

export function ViewTransitions() {
  const pathname = usePathname()
  const router = useRouter()
  const previousPathRef = useRef(pathname)

  useEffect(() => {
    previousPathRef.current = pathname
  }, [pathname])

  useEffect(() => {
    // Check if browser supports View Transitions API
    if (!('startViewTransition' in document)) {
      return
    }

    const handleClick = (e: MouseEvent) => {
      const target = e.target as HTMLElement
      const link = target.closest('a')

      // Only intercept internal same-origin links
      if (
        !link ||
        link.target === '_blank' ||
        link.hostname !== window.location.hostname ||
        link.pathname === window.location.pathname ||
        e.metaKey ||
        e.ctrlKey ||
        e.shiftKey ||
        e.altKey
      ) {
        return
      }

      e.preventDefault()

      const targetPath = link.pathname
      const currentPath = window.location.pathname

      // Determine navigation direction
      const isNavigatingToDetail = targetPath.includes('/product/') && currentPath === '/'
      const isNavigatingBack = targetPath === '/' && currentPath.includes('/product/')

      // Set direction class on document for CSS
      if (isNavigatingBack) {
        document.documentElement.classList.add('back-navigation')
      } else if (isNavigatingToDetail) {
        document.documentElement.classList.add('forward-navigation')
      }

      // Start the view transition
      const transition = (document as any).startViewTransition(() => {
        // Navigate using Next.js router
        router.push(targetPath)
      })

      // Clean up direction classes after transition
      transition.finished.finally(() => {
        document.documentElement.classList.remove('back-navigation', 'forward-navigation')
      })
    }

    document.addEventListener('click', handleClick)
    return () => document.removeEventListener('click', handleClick)
  }, [router])

  return null
}

